<script setup lang="ts">
import { uiText, uiLocale } from '@/i18n'

import { onMounted,ref } from 'vue'
import { researchApi,type RecordItem } from '@/api/research'
interface EvaluationRow{sample:string;expected:string;model:string;version:string;output:string;status:string;latencyMs:number|null;costCny:number|null}
const title=ref('识别对照实验'),parameters=ref('说明任务类型、提示词、预处理参数与数据来源'),provenance=ref('IMPORTED'),ignoreCase=ref(false),busy=ref(false),error=ref(''),reports=ref<RecordItem[]>([]),selected=ref<RecordItem|null>(null)
const rows=ref<EvaluationRow[]>([])
function add(){rows.value.push({sample:'sample-'+(rows.value.length+1),expected:'',model:'',version:'',output:'',status:'OK',latencyMs:null,costCny:null})}
function download(data:unknown,name:string){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function template(){download([{sample:'sample-1',expected:'标准答案',model:'模型名称',version:'版本或日期',output:'识别输出',status:'OK',latencyMs:null,costCny:null}],'evaluation-template.json')}
async function importRows(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{if(file.size>1500000)throw new Error('导入文件不能超过 1.5 MB');const value=JSON.parse(await file.text());if(!Array.isArray(value)||value.length>500)throw new Error('文件应为不超过 500 行的 JSON 数组');if(value.some(r=>!r||typeof r!=='object'||!['sample','expected','model','version'].every(k=>typeof r[k]==='string')||!['OK','FAILED'].includes(r.status)||(r.output!=null&&typeof r.output!=='string')||['latencyMs','costCny'].some(k=>r[k]!=null&&(typeof r[k]!=='number'||!Number.isFinite(r[k])||r[k]<0))))throw new Error('预测行格式不正确，请按模板填写文字字段、状态和数字');rows.value=value.map(r=>({...r,output:r.output??'',latencyMs:r.latencyMs??null,costCny:r.costCny??null}));error.value=''}catch(e){error.value=(e as Error).message}finally{input.value=''}}
async function evaluate(){busy.value=true;error.value='';try{selected.value=await researchApi.evaluate({title:title.value,parameters:parameters.value,provenance:provenance.value,ignoreCase:ignoreCase.value,rows:rows.value});reports.value=await researchApi.evaluations()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(async()=>{try{reports.value=await researchApi.evaluations()}catch(e){error.value=(e as Error).message}})
</script>
<template><section><p v-if="error" role="alert" class="inline-alert inline-alert--error">{{ uiText(error) }}</p><div class="research-section-title"><h2>{{ uiText('用相同样本比较模型') }}</h2><button class="button button--ghost" @click="template">{{ uiText('下载导入模板') }}</button></div><p class="research-hint">{{ uiText('导入或填写一批模型预测，按相同样本编号对照标准答案。缺失输出计为失败；每份报告保存当时的数据、模型版本与参数。这里计算指标，不会发起付费模型调用。') }}</p>
 <div class="benchmark-meta"><label>{{ uiText('实验名称') }}<input v-model="title" class="field-input" maxlength="180"/></label><label>{{ uiText('数据来源') }}<select v-model="provenance" class="field-input"><option value="IMPORTED">{{ uiText('外部实际预测（来源由提交者提供）') }}</option><option value="DEMO">{{ uiText('演示／合成数据') }}</option></select></label><label>{{ uiText('匹配规则') }}<select v-model="ignoreCase" class="field-input"><option :value="false">{{ uiText('忽略首尾空白，区分大小写') }}</option><option :value="true">{{ uiText('忽略首尾空白和大小写') }}</option></select></label></div><label class="benchmark-parameters">{{ uiText('实验参数与数据说明') }}<textarea v-model="parameters" class="field-input" maxlength="2000" rows="2"/></label>
 <div class="research-actions"><button class="button button--ghost" :disabled="rows.length>=500" @click="add">{{ uiText('＋ 添加预测') }}</button><label class="button button--ghost">{{ uiText('导入 JSON') }}<input type="file" accept=".json" hidden @change="importRows"/></label><button class="button button--dark" :disabled="busy||!rows.length" @click="evaluate">{{ busy?uiText('计算中…'):uiText('计算并保存报告') }}</button></div>
 <div class="benchmark-grid"><table class="research-table"><thead><tr><th>{{ uiText('样本编号') }}</th><th>{{ uiText('标准答案') }}</th><th>{{ uiText('模型') }}</th><th>{{ uiText('版本') }}</th><th>{{ uiText('输出') }}</th><th>{{ uiText('状态') }}</th><th>{{ uiText('耗时 ms') }}</th><th>{{ uiText('费用 ¥') }}</th><th/></tr></thead><tbody><tr v-for="(r,i) in rows" :key="i"><td><input v-model="r.sample" maxlength="80"/></td><td><input v-model="r.expected" maxlength="500"/></td><td><input v-model="r.model" maxlength="120"/></td><td><input v-model="r.version" maxlength="80"/></td><td><input v-model="r.output" maxlength="500"/></td><td><select v-model="r.status"><option>OK</option><option>FAILED</option></select></td><td><input v-model.number="r.latencyMs" type="number" min="0"/></td><td><input v-model.number="r.costCny" type="number" min="0" step="0.000001"/></td><td><button class="result-title" @click="rows.splice(i,1)">{{ uiText('移除') }}</button></td></tr></tbody></table></div>
 <div class="research-section-title benchmark-reports"><h2>{{ uiText('已保存的实验') }}</h2><select class="field-input" :value="selected?.id||''" :aria-label="uiText('选择实验报告')" @change="selected=reports.find(r=>r.id===($event.target as HTMLSelectElement).value)||null"><option value="">{{ uiText('选择报告') }}</option><option v-for="r in reports" :key="r.id" :value="r.id">{{ r.title }} · {{ new Date(r.updatedAt).toLocaleDateString(uiLocale()) }}</option></select></div>
 <section v-if="selected" class="research-card"><div class="research-section-title"><h2>{{ selected.title }}</h2><button class="button button--ghost" @click="download(selected,'evaluation-report.json')">{{ uiText('导出完整报告') }}</button></div><p class="research-hint">{{ selected.data.provenance==='DEMO'?uiText('演示数据 · 不能作为真实性能结论'):uiText('外部导入预测 · 平台未独立验证预测来源') }} {{ uiText('· 样本') }} {{ selected.data.sampleCount }} {{ uiText('个') }}</p><table class="research-table"><thead><tr><th>{{ uiText('模型／版本') }}</th><th>{{ uiText('完全匹配率') }}</th><th>{{ uiText('字符错误率') }}</th><th>{{ uiText('失败／缺失') }}</th><th>{{ uiText('平均耗时') }}</th><th>{{ uiText('已知费用') }}</th></tr></thead><tbody><tr v-for="m in selected.data.metrics" :key="JSON.stringify([m.modelId,m.version])"><td>{{ m.model }}</td><td>{{ (m.accuracy*100).toFixed(1) }}%</td><td>{{ (m.characterErrorRate*100).toFixed(1) }}%</td><td>{{ m.failed }} / {{ m.samples }}</td><td>{{ m.averageLatencyMs==null?uiText('未提供'):m.averageLatencyMs.toFixed(0)+' ms' }}<small>（{{ m.latencySamples }} {{ uiText('条）') }}</small></td><td>{{ m.knownCostCny==null?uiText('未提供'):'¥'+m.knownCostCny }}<small>（{{ m.costSamples }} {{ uiText('条）') }}</small></td></tr></tbody></table><p class="research-hint">{{ uiText('字符错误率可超过 100%。时间和费用仅统计已提供的成功样本，空值不会当成零。适用于有明确文本标准答案的识别任务。') }}</p><details><summary>{{ uiText('数据指纹与实验参数') }}</summary><code>{{ selected.data.datasetHash }}</code><pre>{{ selected.data.parameters }}</pre></details></section>
 </section></template>
<style scoped>.benchmark-meta{display:grid;grid-template-columns:1fr 1fr 1fr;gap:20px;margin:25px 0}.benchmark-meta label,.benchmark-parameters{display:grid;gap:8px;font-size:13px}.benchmark-grid{overflow:auto;margin:22px 0}.benchmark-grid input,.benchmark-grid select{width:100%;min-width:90px;max-width:180px;background:none;border:1px solid var(--line);color:var(--ink);padding:9px;font-size:12px}.benchmark-reports{margin-top:40px}.benchmark-reports select{max-width:480px}.research-card code{overflow-wrap:anywhere;font-size:11px}.research-card pre{white-space:pre-wrap}.research-table small{display:block;color:var(--muted);font-size:10px}</style>
